//! Current journal record shape and canonical body ownership. A parsed record
//! is neither a durable append, an authenticated journal prefix nor authority.
use opensip_identity::{JsonValue as V, raw_sha256};
use std::collections::BTreeMap;
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) enum JournalError {
    Metadata,
    Shape,
    MixedPrefix,
    Historical,
    Unsupported,
    Schema,
    SealType,
    SealRunRequired,
    FixtureRun,
    RunMismatch,
}
pub(super) struct JournalRecord {
    body: V,
    canonical: Vec<u8>,
    body_sha256: [u8; 32],
}
fn object(v: &V) -> Option<&BTreeMap<String, V>> {
    if let V::Object(v) = v { Some(v) } else { None }
}
fn text(v: &V) -> Option<&str> {
    if let V::String(v) = v { Some(v) } else { None }
}
fn number(v: &V) -> Option<i64> {
    if let V::Integer(v) = v {
        i64::try_from(v.get()).ok()
    } else {
        None
    }
}
fn bounded_text(v: &V, min: usize, max: usize) -> bool {
    text(v).is_some_and(|s| {
        let n = s.chars().count();
        n >= min && n <= max
    })
}
fn hex(s: &str) -> bool {
    s.len() == 64
        && s.bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}
impl JournalRecord {
    pub(super) fn parse(raw: &[u8]) -> Result<Self, JournalError> {
        let body = crate::trust::metadata::parse(raw).map_err(|_| JournalError::Metadata)?;
        let canonical =
            crate::trust::metadata::encode(&body).map_err(|_| JournalError::Metadata)?;
        let q = object(&body).ok_or(JournalError::Shape)?;
        let schema = q.get("recordSchema").and_then(number);
        let run = q.get("runId").and_then(text);
        match schema {
            Some(3) => {
                if run.is_some_and(|s| s.starts_with("run2:")) {
                    return Err(JournalError::MixedPrefix);
                }
            }
            Some(2) => {
                return Err(if run.is_some_and(|s| s.starts_with("run3:")) {
                    JournalError::MixedPrefix
                } else {
                    JournalError::Historical
                });
            }
            _ => return Err(JournalError::Unsupported),
        }
        const REQUIRED: [&str; 5] = [
            "recordType",
            "recordSchema",
            "grantGeneration",
            "seq",
            "operationRef",
        ];
        const OPTIONAL: [&str; 8] = [
            "grant",
            "requestRef",
            "outcome",
            "postimageSha256",
            "reason",
            "trustEpochObserved",
            "residuals",
            "runId",
        ];
        if REQUIRED.iter().any(|k| !q.contains_key(*k))
            || q.keys()
                .any(|k| !REQUIRED.contains(&k.as_str()) && !OPTIONAL.contains(&k.as_str()))
        {
            return Err(JournalError::Schema);
        }
        if !text(&q["recordType"]).is_some_and(|s| {
            [
                "GRANT", "RA", "ICI", "RCI", "ICO", "RCO", "REV", "CLN", "SEAL",
            ]
            .contains(&s)
        }) || number(&q["grantGeneration"]).is_none_or(|n| n <= 0)
            || number(&q["seq"]).is_none_or(|n| n <= 0)
            || !bounded_text(&q["operationRef"], 1, 128)
        {
            return Err(JournalError::Schema);
        }
        for key in ["grant", "requestRef", "reason"] {
            if q.get(key).is_some_and(|v| !bounded_text(v, 0, 256)) {
                return Err(JournalError::Schema);
            }
        }
        if q.get("outcome")
            .is_some_and(|v| text(v) != Some("COMPLETED"))
            || q.get("postimageSha256")
                .is_some_and(|v| !text(v).is_some_and(hex))
            || q.get("trustEpochObserved")
                .is_some_and(|v| object(v).is_none())
            || q.get("runId").is_some_and(|v| {
                !text(v)
                    .and_then(|s| s.strip_prefix("run3:"))
                    .is_some_and(hex)
            })
        {
            return Err(JournalError::Schema);
        }
        if let Some(v) = q.get("residuals") {
            let V::Array(a) = v else {
                return Err(JournalError::Schema);
            };
            if a.len() > 4096 || a.iter().any(|v| !bounded_text(v, 0, 4096)) {
                return Err(JournalError::Schema);
            }
        }

        let mut preimage = b"opensip.metadata.journal.1\0".to_vec();
        preimage.extend_from_slice(&canonical);
        let body_sha256 = raw_sha256(&preimage);
        Ok(Self {
            body,
            canonical,
            body_sha256,
        })
    }
    pub(super) fn body(&self) -> &V {
        &self.body
    }
    pub(super) fn canonical(&self) -> &[u8] {
        &self.canonical
    }
    pub(super) fn body_sha256(&self) -> [u8; 32] {
        self.body_sha256
    }
    pub(super) fn seal_run_id(&self) -> Result<&str, JournalError> {
        let q = object(&self.body).expect("owned admitted record");
        if text(&q["recordType"]) != Some("SEAL") {
            return Err(JournalError::SealType);
        }
        let id = q
            .get("runId")
            .and_then(text)
            .ok_or(JournalError::SealRunRequired)?;
        if id
            .strip_prefix("run3:")
            .is_some_and(|s| s.bytes().all(|b| b == b'0'))
        {
            return Err(JournalError::FixtureRun);
        }
        Ok(id)
    }
}

// Inert current-generation prefix checks under selected carrierFormat3 chain_law1.
// Supplied rows are not an authenticated/current/durable carrier snapshot.
const CARRIER_CAP: i64 = 9_007_199_254_740_991;
/// The highest committed tail a `SEAL` may follow: it takes at most
/// `9007199254740988`, leaving `…989` and `…990` for its end path's `REV` and
/// `CLN` (X3b r8 item 5a).
const SEAL_CEILING: i64 = CARRIER_CAP - 4;
/// X3b r8 item 5a's exported predicate: whether a `SEAL` fits after the
/// committed tail `tail` of an open generation (`tail ≤ 9007199254740987`).
/// When it is false the generation is exhausted: X3d-1's `prepare_commit`
/// returns `CarrierCapacityExhausted`, and it is the only condition on which
/// the rollover appends `TERMINAL`. No caller writes the threshold itself;
/// the append's `SealCeiling` check uses it too.
pub(crate) fn seal_fits(tail: i64) -> bool {
    tail <= SEAL_CEILING
}
#[derive(Debug, PartialEq, Eq)]
enum PrefixError {
    Bound,
    Generation,
    Sequence,
    Shape,
    Canonical,
    BodyDigest,
    PreviousDigest,
    RowBinding,
    AfterTerminal,
}
struct CarrierRow {
    generation: i64,
    seq: i64,
    schema: i64,
    kind: String,
    operation: String,
    run: Option<String>,
    body: Vec<u8>,
    body_sha: String,
    previous_sha: String,
}
struct CheckedRecord {
    row: CarrierRow,
    terminal: bool,
    closes_generation: bool,
}
struct GenerationPrefix {
    project_digest: [u8; 32],
    generation: i64,
    records: Vec<CheckedRecord>,
}
fn genesis_previous(project_key: &str, generation: i64) -> [u8; 32] {
    let mut preimage = b"opensip.journal.genesis.1\0".to_vec();
    preimage.extend_from_slice(project_key.as_bytes());
    preimage.push(0);
    preimage.extend_from_slice(generation.to_string().as_bytes());
    raw_sha256(&preimage)
}
fn following_previous(body_sha: &[u8; 32], seq: i64) -> [u8; 32] {
    let mut preimage = opensip_identity::digest_hex(body_sha).into_bytes();
    preimage.extend_from_slice(seq.to_string().as_bytes());
    raw_sha256(&preimage)
}
fn terminal_body(raw: &[u8]) -> Result<(V, Vec<u8>, [u8; 32]), PrefixError> {
    let v = crate::trust::metadata::parse(raw).map_err(|_| PrefixError::Canonical)?;
    let canonical = crate::trust::metadata::encode(&v).map_err(|_| PrefixError::Canonical)?;
    let q = object(&v).ok_or(PrefixError::Shape)?;
    let keys = [
        "recordSchema",
        "grantGeneration",
        "seq",
        "operationRef",
        "wallClockData",
        "recordType",
        "cause",
    ];
    if q.len() != keys.len() || keys.iter().any(|k| !q.contains_key(*k)) {
        return Err(PrefixError::Shape);
    }
    let wall = text(&q["wallClockData"]).ok_or(PrefixError::Shape)?;
    let wall_shape = wall.len() == 20
        && wall.bytes().enumerate().all(|(i, b)| match i {
            4 | 7 => b == b'-',
            10 => b == b'T',
            13 | 16 => b == b':',
            19 => b == b'Z',
            _ => b.is_ascii_digit(),
        });
    let operation = text(&q["operationRef"]).ok_or(PrefixError::Shape)?;
    if number(&q["recordSchema"]) != Some(1)
        || number(&q["grantGeneration"]).is_none_or(|n| n < 1)
        || number(&q["seq"]).is_none_or(|n| !(1..=CARRIER_CAP).contains(&n))
        || text(&q["recordType"]) != Some("TERMINAL")
        || !text(&q["cause"])
            .is_some_and(|c| ["projectPurge", "grantGenerationClosure"].contains(&c))
        || !operation.strip_prefix("op-").is_some_and(|s| {
            s.len() == 32
                && s.bytes()
                    .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
        })
        || !wall_shape
    {
        return Err(PrefixError::Shape);
    }
    // Frozen wallClockData is a lexical data field, not a trusted time input;
    // do not silently add a calendar-admission rule to its inherited schema.
    let mut preimage = b"opensip.metadata.journal.1\0".to_vec();
    preimage.extend_from_slice(&canonical);
    let digest = raw_sha256(&preimage);
    Ok((v, canonical, digest))
}
impl GenerationPrefix {
    fn verify(
        project_key: &str,
        generation: i64,
        rows: Vec<CarrierRow>,
        max_records: usize,
        max_body_bytes: usize,
    ) -> Result<Self, PrefixError> {
        if generation < 1 {
            return Err(PrefixError::Generation);
        }
        if rows.len() > max_records {
            return Err(PrefixError::Bound);
        }
        let total = rows
            .iter()
            .try_fold(0usize, |sum, row| sum.checked_add(row.body.len()))
            .ok_or(PrefixError::Bound)?;
        if total > max_body_bytes {
            return Err(PrefixError::Bound);
        }
        let mut expected_previous = genesis_previous(project_key, generation);
        let mut records = Vec::new();
        let mut closed = false;
        for (i, row) in rows.into_iter().enumerate() {
            if closed {
                return Err(PrefixError::AfterTerminal);
            }
            if row.generation != generation {
                return Err(PrefixError::Generation);
            }
            if row.seq
                != i64::try_from(i)
                    .ok()
                    .and_then(|n| n.checked_add(1))
                    .ok_or(PrefixError::Sequence)?
                || row.seq > CARRIER_CAP
            {
                return Err(PrefixError::Sequence);
            }
            let terminal = row.schema == 1 && row.kind == "TERMINAL";
            let (v, canonical, digest) = if terminal {
                terminal_body(&row.body)?
            } else {
                if row.schema != 3 || row.seq == CARRIER_CAP {
                    return Err(PrefixError::Shape);
                }
                let record = JournalRecord::parse(&row.body).map_err(|_| PrefixError::Shape)?;
                (record.body, record.canonical, record.body_sha256)
            };
            if row.body != canonical {
                return Err(PrefixError::Canonical);
            }
            let q = object(&v).ok_or(PrefixError::Shape)?;
            if number(&q["grantGeneration"]) != Some(generation)
                || number(&q["seq"]) != Some(row.seq)
                || text(&q["recordType"]) != Some(row.kind.as_str())
                || text(&q["operationRef"]) != Some(row.operation.as_str())
                || q.get("runId").and_then(text) != row.run.as_deref()
            {
                return Err(PrefixError::RowBinding);
            }
            // Physical operation_ref is narrower than logical JournalRecord3.
            if !row.operation.strip_prefix("op-").is_some_and(|s| {
                s.len() == 32
                    && s.bytes()
                        .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
            }) {
                return Err(PrefixError::RowBinding);
            }
            if row.kind == "SEAL"
                && row
                    .run
                    .as_ref()
                    .is_none_or(|s| !s.strip_prefix("run3:").is_some_and(hex))
            {
                return Err(PrefixError::RowBinding);
            }
            if row.body_sha != opensip_identity::digest_hex(&digest) {
                return Err(PrefixError::BodyDigest);
            }
            if row.previous_sha != opensip_identity::digest_hex(&expected_previous) {
                return Err(PrefixError::PreviousDigest);
            }
            expected_previous = following_previous(&digest, row.seq);
            closed = terminal;
            // Both TERMINAL causes stop further appends in this generation.
            // Only this cause can justify an immediate next generation.
            let closes_generation = terminal
                && object(&v).and_then(|q| q.get("cause")).and_then(text)
                    == Some("grantGenerationClosure");
            records.push(CheckedRecord {
                row,
                terminal,
                closes_generation,
            });
        }
        Ok(Self {
            project_digest: raw_sha256(project_key.as_bytes()),
            generation,
            records,
        })
    }
}

// Private read-only current-format SQLite capture. Path/sidecar custody and
// admitted registry ownership are supplied; this creates no recovery authority.
use rusqlite::{Connection, OpenFlags, config::DbConfig, limits::Limit};
use std::{
    path::{Component, Path},
    time::Duration,
};
#[derive(Debug)]
enum CarrierReadError {
    Path,
    Io(std::io::Error),
    Sql(rusqlite::Error),
    Definition,
    Configuration,
    Unpublished,
    Binding,
    Historical,
    MigrationRequiresValidation,
    PhysicalRow,
    Bound,
    Prefix(PrefixError),
}
impl From<rusqlite::Error> for CarrierReadError {
    fn from(e: rusqlite::Error) -> Self {
        Self::Sql(e)
    }
}
struct CurrentCarrierSnapshot {
    connection: Connection,
    project_key: String,
    first_generation: i64,
    inherited_format: Option<inherited_schema::InheritedFormat>,
}
type CarrierDefinition = (String, String, Option<String>);
fn carrier_definitions(c: &Connection) -> rusqlite::Result<Vec<CarrierDefinition>> {
    c.prepare("SELECT type,name,sql FROM main.sqlite_schema WHERE tbl_name IN ('carrier_format','grant_journal_v3','carrier_quarantine','carrier_capacity_pause') ORDER BY type,name")?.query_map([],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?)))?.collect()
}
// Opens one actual read-only WAL transaction. The first subsequent schema read
// fixes its snapshot; callers must retain this connection through classification.
fn read_only_carrier_connection(path: &Path) -> Result<Connection, CarrierReadError> {
    if !path.is_absolute()
        || path
            .components()
            .any(|c| !matches!(c, Component::RootDir | Component::Normal(_)))
    {
        return Err(CarrierReadError::Path);
    }
    if !std::fs::symlink_metadata(path)
        .map_err(CarrierReadError::Io)?
        .file_type()
        .is_file()
    {
        return Err(CarrierReadError::Path);
    }
    let c = Connection::open_with_flags(
        path,
        OpenFlags::SQLITE_OPEN_READ_ONLY
            | OpenFlags::SQLITE_OPEN_NO_MUTEX
            | OpenFlags::SQLITE_OPEN_PRIVATE_CACHE
            | OpenFlags::SQLITE_OPEN_NOFOLLOW,
    )?;
    if !c.is_readonly(rusqlite::MAIN_DB)? {
        return Err(CarrierReadError::Configuration);
    }
    configure_reader_controls(&c)?;
    let journal: String = c.query_row("PRAGMA journal_mode", [], |r| r.get(0))?;
    if journal != "wal" {
        return Err(CarrierReadError::Configuration);
    }
    c.execute_batch("BEGIN")?;
    Ok(c)
}
// This stage may execute connection-control SQL, never data/schema queries.
// The open boundary checks READ_ONLY separately; tests exercise defense in depth
// on a deliberately writable scratch connection without exposing such an opener.
fn configure_reader_controls(c: &Connection) -> Result<(), CarrierReadError> {
    c.busy_timeout(Duration::ZERO)?;
    // Configure through the safe engine API before any SQL can attach WAL/SHM.
    // Sidecar custody and the admitted reader lease remain separate prerequisites.
    if !c.set_db_config(DbConfig::SQLITE_DBCONFIG_NO_CKPT_ON_CLOSE, true)?
        || !c.db_config(DbConfig::SQLITE_DBCONFIG_NO_CKPT_ON_CLOSE)?
    {
        return Err(CarrierReadError::Configuration);
    }
    for (limit, value) in [
        (Limit::SQLITE_LIMIT_LENGTH, 4 * 1024 * 1024),
        (Limit::SQLITE_LIMIT_SQL_LENGTH, 262144),
        (Limit::SQLITE_LIMIT_ATTACHED, 0),
    ] {
        c.set_limit(limit, value)?;
        if c.limit(limit)? != value {
            return Err(CarrierReadError::Bound);
        }
    }
    for (option, value) in [
        (DbConfig::SQLITE_DBCONFIG_DEFENSIVE, true),
        (DbConfig::SQLITE_DBCONFIG_DQS_DML, false),
        (DbConfig::SQLITE_DBCONFIG_DQS_DDL, false),
    ] {
        if c.set_db_config(option, value)? != value {
            return Err(CarrierReadError::Configuration);
        }
    }
    c.execute_batch("PRAGMA query_only=ON; PRAGMA trusted_schema=OFF; PRAGMA foreign_keys=ON;")?;
    for (name, value) in [
        ("query_only", 1),
        ("trusted_schema", 0),
        ("foreign_keys", 1),
        ("busy_timeout", 0),
    ] {
        let actual: i64 = c.query_row(&format!("PRAGMA {name}"), [], |r| r.get(0))?;
        if actual != value {
            return Err(CarrierReadError::Configuration);
        }
    }
    Ok(())
}
fn admit_carrier_definitions(
    c: &Connection,
) -> Result<Option<inherited_schema::InheritedFormat>, CarrierReadError> {
    let inherited_format = inherited_schema::admit(c)?;
    let expected = Connection::open_in_memory()?;
    if let Some(format) = &inherited_format {
        // Auxiliary definitions stay exactly as the inherited format created
        // them. The additive v3 DDL must not overwrite those frozen bytes.
        expected.execute_batch(format.ddl())?;
    }
    expected.execute_batch(CURRENT_CARRIER_DDL)?;
    if carrier_definitions(c)? != carrier_definitions(&expected)? {
        return Err(CarrierReadError::Definition);
    }
    Ok(inherited_format)
}
impl CurrentCarrierSnapshot {
    fn open(path: &Path, project_key: &str) -> Result<Self, CarrierReadError> {
        let c = read_only_carrier_connection(path)?;
        let admitted = carrier_dispatch::admit_connection(c)?;
        Self::from_admitted_connection(admitted, project_key)
    }
    fn from_admitted_connection(
        admitted: carrier_dispatch::AdmittedCarrierConnection,
        project_key: &str,
    ) -> Result<Self, CarrierReadError> {
        let (c, inherited_format) = admitted.into_parts();
        let first_generation = {
            let mut s=c.prepare("SELECT singleton,carrier_format,project_key_digest,first_generation,chain_law,migrated_from,migration_op_ref FROM carrier_format LIMIT 2")?;
            let mut rows = s.query([])?;
            let row = rows.next()?.ok_or(CarrierReadError::Unpublished)?;
            let singleton: i64 = row.get(0)?;
            let format: i64 = row.get(1)?;
            let project: String = row.get(2)?;
            let first: i64 = row.get(3)?;
            let law: i64 = row.get(4)?;
            let migrated: Option<i64> = row.get(5)?;
            let op: Option<String> = row.get(6)?;
            let migrated_shape = match (migrated, op.as_deref()) {
                (None, None) => first == 1,
                (Some(1 | 2), Some(op)) => first >= 2 && physical_operation(op),
                _ => false,
            };
            if singleton != 1
                || format != 3
                || law != 1
                || !migrated_shape
                || rows.next()?.is_some()
            {
                return Err(CarrierReadError::Definition);
            }
            if project != opensip_identity::digest_hex(&raw_sha256(project_key.as_bytes())) {
                return Err(CarrierReadError::Binding);
            }
            if migrated != inherited_format.as_ref().map(|format| format.number()) {
                return Err(CarrierReadError::MigrationRequiresValidation);
            }
            if inherited_format.is_some() {
                // Publication C fixed first_generation at max inherited + 1.
                // Full prefix/origin/closure admission follows in capture_population.
                let maximum: Option<i64> =
                    c.query_row("SELECT MAX(grantGeneration) FROM grant_journal", [], |r| {
                        r.get(0)
                    })?;
                if maximum != first.checked_sub(1) {
                    return Err(CarrierReadError::MigrationRequiresValidation);
                }
            }
            first
        };
        // Rows below the published generation boundary make the current carrier
        // inconsistent; never hide them by querying only the requested generation.
        let invalid: bool = c.query_row(
            "SELECT EXISTS(SELECT 1 FROM grant_journal_v3 WHERE grantGeneration<?1)",
            [first_generation],
            |r| r.get(0),
        )?;
        if invalid {
            return Err(CarrierReadError::PhysicalRow);
        }
        Ok(Self {
            connection: c,
            project_key: project_key.into(),
            first_generation,
            inherited_format,
        })
    }
    fn capture_population(
        &self,
        max_generations: usize,
        max_records: usize,
        max_body_bytes: usize,
    ) -> Result<generation_population::AdmittedPopulation, generation_population::PopulationError>
    {
        generation_population::capture(self, max_generations, max_records, max_body_bytes)
    }
    // A marker observation is not generation-population or continuation authority.
    fn capture_marker(
        &self,
        generation: i64,
        max_body_bytes: usize,
    ) -> Result<marker_rows::Observation, CarrierReadError> {
        if generation < self.first_generation {
            return Err(CarrierReadError::Historical);
        }
        if max_body_bytes == 0 {
            return Err(CarrierReadError::Bound);
        }
        marker_rows::capture(
            &self.connection,
            &self.project_key,
            generation,
            max_body_bytes,
        )
        .map_err(CarrierReadError::Sql)
    }
    fn capture(
        &self,
        generation: i64,
        max_records: usize,
        max_body_bytes: usize,
    ) -> Result<GenerationPrefix, CarrierReadError> {
        if generation < self.first_generation {
            return Err(CarrierReadError::Historical);
        }
        let limit = i64::try_from(max_records)
            .ok()
            .and_then(|n| n.checked_add(1))
            .ok_or(CarrierReadError::Bound)?;
        let mut statement=self.connection.prepare("SELECT grantGeneration,seq,record_schema,record_type,operation_ref,request_ref,token,install_generation_id,manifest_digest,platform,run_id,body,body_sha256,prev_sha256 FROM grant_journal_v3 WHERE grantGeneration=?1 ORDER BY seq LIMIT ?2")?;
        let mut cursor = statement.query(rusqlite::params![generation, limit])?;
        let mut rows = Vec::new();
        let mut total = 0usize;
        while let Some(r) = cursor.next()? {
            if rows.len() == max_records {
                return Err(CarrierReadError::Bound);
            }
            let request: Option<String> = r.get(5)?;
            let token: Option<String> = r.get(6)?;
            let install: Option<String> = r.get(7)?;
            let manifest: Option<String> = r.get(8)?;
            let platform: Option<String> = r.get(9)?;
            let body: String = r.get(11)?;
            total = total
                .checked_add(body.len())
                .ok_or(CarrierReadError::Bound)?;
            if total > max_body_bytes {
                return Err(CarrierReadError::Bound);
            }
            let row = CarrierRow {
                generation: r.get(0)?,
                seq: r.get(1)?,
                schema: r.get(2)?,
                kind: r.get(3)?,
                operation: r.get(4)?,
                run: r.get(10)?,
                body: body.into_bytes(),
                body_sha: r.get(12)?,
                previous_sha: r.get(13)?,
            };
            if !physical_operation(&row.operation)
                || manifest.as_ref().is_some_and(|s| !hex(s))
                || platform.as_deref().is_some_and(|s| {
                    ![
                        "macos-aarch64",
                        "macos-x86_64",
                        "linux-x86_64-gnu",
                        "linux-aarch64-gnu",
                    ]
                    .contains(&s)
                })
                || row
                    .run
                    .as_ref()
                    .is_some_and(|s| !s.strip_prefix("run3:").is_some_and(hex))
            {
                return Err(CarrierReadError::PhysicalRow);
            }
            if row.kind == "GRANT"
                && (token.is_none()
                    || install.is_none()
                    || manifest.is_none()
                    || platform.is_none())
            {
                return Err(CarrierReadError::PhysicalRow);
            }
            if row.kind == "TERMINAL"
                && (request.is_some()
                    || token.is_some()
                    || install.is_some()
                    || manifest.is_some()
                    || platform.is_some()
                    || row.run.is_some())
            {
                return Err(CarrierReadError::PhysicalRow);
            }
            // request_ref is an optional physical mirror of the logical field.
            let value = crate::trust::metadata::parse(&row.body)
                .map_err(|_| CarrierReadError::PhysicalRow)?;
            let q = object(&value).ok_or(CarrierReadError::PhysicalRow)?;
            if q.get("requestRef").and_then(text) != request.as_deref() {
                return Err(CarrierReadError::PhysicalRow);
            }
            rows.push(row);
        }
        GenerationPrefix::verify(
            &self.project_key,
            generation,
            rows,
            max_records,
            max_body_bytes,
        )
        .map_err(CarrierReadError::Prefix)
    }
}
fn physical_operation(op: &str) -> bool {
    op.strip_prefix("op-").is_some_and(|s| {
        s.len() == 32
            && s.bytes()
                .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
    })
}
impl Drop for CurrentCarrierSnapshot {
    fn drop(&mut self) {
        let _ = self.connection.execute_batch("ROLLBACK");
    }
}

const CURRENT_CARRIER_DDL: &str = r####"-- OpenSIP product grant-journal physical carrier, carrierFormat 3 (PROPOSED).
-- Standing: PROPOSED-NOT-SELF-ACCEPTED. Design/reference only: no acceptance, no readiness,
-- no application and no implementation authorization.
-- Additive successor to the frozen historical carriers. Creates new objects only.
-- It never alters, rewrites, relabels or reinterprets a carrierFormat 1 or 2 row,
-- and it disables no inherited constraint or trigger.
--
-- Three independent axes, never conflated:
--   carrierFormat  1 | 2 | 3   physical table/trigger shape of this SQLite carrier
--   recordSchema   1 | 2 | 3   logical journal record body format (security-owned)
--   stateSchema    1 | 2       logical store state format (S9, StoreGenerationBindingV1)
--
-- carrierFormat 1: security-completion.v1 section 5.4 embedded DDL.
-- carrierFormat 2: security-schemas.v2/grant-journal.sql (adds the uint53 seq CHECK,
--                  operation_ref format, contiguity, TERMINAL closure, reserved slot).
-- carrierFormat 3: this file.
--
-- Source37 owner correction (review advisories A37-01 and A37-02). Revised after root reproduced embedded-NUL
-- and ASCII-hex BLOB admissions against the source37 v1 bytes, and again after root showed that the source37 v2
-- byte-length predicate refused lawful rows in UTF-16 databases. These bytes supersede the earlier PROPOSED
-- carrierFormat 3 bytes in place. No product implementation or deployed carrier was created from the earlier
-- bytes. Reference in-memory SQLite instances were created from them by earlier design checks and review
-- probes; those instances and their receipts remain historical evidence. The open dispatch validates the
-- stored definitions byte-exactly, so a carrier created from earlier bytes is refused MIGRATION.CORRUPT
-- rather than read as this definition. carrierFormat 1 and 2 bytes stay frozen.
--
-- Storage class and whole-value grammar. SQLite types values dynamically: TEXT affinity keeps a BLOB,
-- INTEGER affinity keeps a non-integral REAL, and length() and GLOB stop at an embedded NUL. Every column's
-- storage class is enforced either by an explicit typeof() guard (every INTEGER column, every free TEXT
-- column and every hex-bearing column) or by exact enumeration (record_type and platform, whose IN lists
-- hold only TEXT literals and so never equal a BLOB, a number or a NUL-suffixed text). Every hex-bearing
-- column is an exact whole TEXT value: typeof(column) = 'text', length(column) = N, no NUL anywhere
-- (instr(column, char(0)) = 0), the prefix GLOB where a prefix exists, and NOT GLOB '*[^0-9a-f]*' over
-- the hex part. With no NUL, length() and GLOB see the whole value, and the case-sensitive hex class admits
-- only ASCII 0-9 and a-f, so multibyte and malformed characters are refused by the same conjunction. The
-- conjunction evaluates the TEXT value by character and does not depend on the database text encoding
-- (exercised under UTF-8, UTF-16le and UTF-16be); no encoding is required of a carrier. CHECKs see values
-- after column affinity, so an integer supplied as text '5' is stored and checked as integer 5. Host
-- record admission still validates the closed record bodies; these CHECKs are defence in depth.
--
-- Publication: no grant_journal_v3 row may exist before the carrier_format row is published, and
-- first_generation is 1 on the fresh path and at least 2 on the migrated path.

CREATE TABLE carrier_format (
  singleton          INTEGER NOT NULL PRIMARY KEY CHECK (typeof(singleton) = 'integer' AND singleton = 1),
  carrier_format     INTEGER NOT NULL CHECK (typeof(carrier_format) = 'integer' AND carrier_format = 3),
  project_key_digest TEXT    NOT NULL CHECK (typeof(project_key_digest) = 'text'
                               AND length(project_key_digest) = 64
                               AND instr(project_key_digest, char(0)) = 0
                               AND project_key_digest NOT GLOB '*[^0-9a-f]*'),
  first_generation   INTEGER NOT NULL CHECK (typeof(first_generation) = 'integer'
                               AND first_generation >= 1
                               AND first_generation <= 9223372036854775807),
  -- Exactly the selected chain law. Value 2 (a recursive chain) is NOT selected and is NOT
  -- implemented, so the column refuses it rather than advertising an unbuilt alternative.
  -- Widening this CHECK is a reviewed successor act, not a configuration choice.
  chain_law          INTEGER NOT NULL CHECK (typeof(chain_law) = 'integer' AND chain_law = 1),
  migrated_from      INTEGER          CHECK (migrated_from IS NULL
                               OR (typeof(migrated_from) = 'integer' AND migrated_from IN (1, 2))),
  migration_op_ref   TEXT             CHECK (migration_op_ref IS NULL
                               OR (typeof(migration_op_ref) = 'text'
                                   AND length(migration_op_ref) = 35
                                   AND instr(migration_op_ref, char(0)) = 0
                                   AND migration_op_ref GLOB 'op-*'
                                   AND substr(migration_op_ref, 4) NOT GLOB '*[^0-9a-f]*')),
  CHECK ((migrated_from IS NULL AND migration_op_ref IS NULL)
      OR (migrated_from IS NOT NULL AND migration_op_ref IS NOT NULL)),
  -- first_generation at publication: the fresh path publishes generation 1 exactly; the migrated path
  -- publishes (max inherited generation) + 1, at least 2 because act A closed a generation >= 1.
  CHECK ((migrated_from IS NULL AND first_generation = 1)
      OR (migrated_from IS NOT NULL AND first_generation >= 2))
) WITHOUT ROWID;
CREATE TRIGGER cf_no_replace BEFORE INSERT ON carrier_format
  WHEN EXISTS(SELECT 1 FROM carrier_format WHERE singleton=NEW.singleton)
  BEGIN SELECT RAISE(ABORT, 'carrier format binding cannot be replaced'); END;
CREATE TRIGGER cf_no_update BEFORE UPDATE ON carrier_format
  BEGIN SELECT RAISE(ABORT, 'carrier format binding is immutable'); END;
CREATE TRIGGER cf_no_delete BEFORE DELETE ON carrier_format
  BEGIN SELECT RAISE(ABORT, 'carrier format binding is immutable'); END;

CREATE TABLE grant_journal_v3 (
  grantGeneration INTEGER NOT NULL CHECK (typeof(grantGeneration) = 'integer'
                              AND grantGeneration >= 1
                              AND grantGeneration <= 9223372036854775807),
  seq          INTEGER NOT NULL CHECK (typeof(seq) = 'integer'
                              AND seq >= 1 AND seq <= 9007199254740991),
  record_schema INTEGER NOT NULL CHECK (typeof(record_schema) = 'integer' AND record_schema IN (1, 3)),
  record_type  TEXT    NOT NULL CHECK (record_type IN
                 ('GRANT','RA','ICI','RCI','ICO','RCO','REV','CLN','SEAL','TERMINAL')),
  operation_ref TEXT   NOT NULL CHECK (typeof(operation_ref) = 'text'
                              AND length(operation_ref) = 35
                              AND instr(operation_ref, char(0)) = 0
                              AND operation_ref GLOB 'op-*'
                              AND substr(operation_ref, 4) NOT GLOB '*[^0-9a-f]*'),
  request_ref  TEXT    CHECK (request_ref IS NULL OR typeof(request_ref) = 'text'),
  token        TEXT    CHECK (token IS NULL OR typeof(token) = 'text'),
  install_generation_id TEXT CHECK (install_generation_id IS NULL OR typeof(install_generation_id) = 'text'),
  manifest_digest TEXT CHECK (manifest_digest IS NULL OR (typeof(manifest_digest) = 'text'
                              AND length(manifest_digest) = 64
                              AND instr(manifest_digest, char(0)) = 0
                              AND manifest_digest NOT GLOB '*[^0-9a-f]*')),
  platform     TEXT    CHECK (platform IS NULL OR platform IN
                 ('macos-aarch64','macos-x86_64','linux-x86_64-gnu','linux-aarch64-gnu')),
  run_id       TEXT    CHECK (run_id IS NULL OR (typeof(run_id) = 'text'
                              AND length(run_id) = 69
                              AND instr(run_id, char(0)) = 0
                              AND run_id GLOB 'run3:*'
                              AND substr(run_id, 6) NOT GLOB '*[^0-9a-f]*')),
  body         TEXT    NOT NULL CHECK (typeof(body) = 'text'),
  body_sha256  TEXT    NOT NULL CHECK (typeof(body_sha256) = 'text'
                              AND length(body_sha256) = 64
                              AND instr(body_sha256, char(0)) = 0
                              AND body_sha256 NOT GLOB '*[^0-9a-f]*'),
  prev_sha256  TEXT    NOT NULL CHECK (typeof(prev_sha256) = 'text'
                              AND length(prev_sha256) = 64
                              AND instr(prev_sha256, char(0)) = 0
                              AND prev_sha256 NOT GLOB '*[^0-9a-f]*'),
  -- Capacity records are the FROZEN recordSchema-1 TERMINAL body
  -- (security-schemas.v2/journal-record.schema.json). Operational records are the
  -- current closed JournalRecord schema 3. TERMINAL is therefore carried without
  -- ever being admitted as a public schema-3 JournalRecord, and schema 3 is not
  -- widened. Never both, never neither.
  CHECK ((record_schema = 3 AND record_type <> 'TERMINAL')
      OR (record_schema = 1 AND record_type = 'TERMINAL')),
  -- Inherited GRANT completeness, retained verbatim in intent.
  CHECK (record_type <> 'GRANT' OR (install_generation_id IS NOT NULL
      AND manifest_digest IS NOT NULL AND platform IS NOT NULL AND token IS NOT NULL)),
  -- A SEAL names its replayed Run; run3 only. No run[23] alternation.
  CHECK (record_type <> 'SEAL' OR run_id IS NOT NULL),
  -- Capacity records carry no grant-bearing or platform-bearing members.
  CHECK (record_type <> 'TERMINAL' OR (token IS NULL AND install_generation_id IS NULL
      AND manifest_digest IS NULL AND platform IS NULL AND run_id IS NULL
      AND request_ref IS NULL)),
  PRIMARY KEY (grantGeneration, seq)
) WITHOUT ROWID;
CREATE TRIGGER gj3_no_update BEFORE UPDATE ON grant_journal_v3
  BEGIN SELECT RAISE(ABORT, 'grant journal is append-only'); END;
CREATE TRIGGER gj3_no_delete BEFORE DELETE ON grant_journal_v3
  BEGIN SELECT RAISE(ABORT, 'grant journal is append-only'); END;
CREATE TRIGGER gj3_append_laws BEFORE INSERT ON grant_journal_v3
  BEGIN
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM carrier_format WHERE singleton = 1)
      THEN RAISE(ABORT, 'carrierFormat 3 is not published; no append precedes the format row') END;
    SELECT CASE WHEN NEW.seq <> (SELECT COALESCE(MAX(seq), 0) + 1 FROM grant_journal_v3
        WHERE grantGeneration = NEW.grantGeneration)
      THEN RAISE(ABORT, 'grant journal sequence must be tail+1') END;
    SELECT CASE WHEN EXISTS (SELECT 1 FROM grant_journal_v3
        WHERE grantGeneration = NEW.grantGeneration AND record_type = 'TERMINAL')
      THEN RAISE(ABORT, 'grant journal carrier is TERMINAL') END;
    SELECT CASE WHEN NEW.seq = 9007199254740991 AND NEW.record_type <> 'TERMINAL'
      THEN RAISE(ABORT, 'grant journal seq 9007199254740991 is the reserved terminal slot; roll the grant generation') END;
    SELECT CASE WHEN NEW.grantGeneration <
        (SELECT first_generation FROM carrier_format WHERE singleton = 1)
      THEN RAISE(ABORT, 'grant generation precedes the carrierFormat 3 first generation') END;
    SELECT CASE WHEN NEW.grantGeneration <
        (SELECT COALESCE(MAX(grantGeneration), 0) FROM grant_journal_v3)
      THEN RAISE(ABORT, 'cannot append to a superseded grant generation') END;
  END;

-- Inherited non-appending side tables. IF NOT EXISTS so that one script serves both
-- fresh creation and migration onto an existing carrierFormat 1/2 database. The open
-- dispatch additionally verifies the stored SQL text of these two tables byte-equals
-- the frozen definition, so IF NOT EXISTS can never silently accept a variant.
CREATE TABLE IF NOT EXISTS carrier_quarantine (
  grantGeneration INTEGER PRIMARY KEY,
  reason     TEXT NOT NULL CHECK (reason IN ('uncertainTailLoss','witnesslessRestore')),
  observed_tail_seq INTEGER,
  body       TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS carrier_capacity_pause (
  grantGeneration INTEGER PRIMARY KEY,
  proven_tail_seq INTEGER NOT NULL,
  reserved_terminal_slot INTEGER NOT NULL DEFAULT 1
);
"####;

// Closed inert witness/floor observations. Decoder profile and actual retained
// file custody are separate owners; these constructors consume exact JSON values.
#[derive(Debug, PartialEq, Eq)]
enum WitnessError {
    Shape,
    Binding,
}
#[derive(Debug, PartialEq, Eq)]
enum WitnessState {
    Pending,
    Committed,
}
struct Witness {
    project: String,
    generation: i64,
    seq: i64,
    body: Option<String>,
    state: WitnessState,
}
struct CarrierFloor {
    project: String,
    generation: i64,
    seq: i64,
    body: Option<String>,
}
fn closed_value<'a>(v: &'a V, keys: &[&str]) -> Result<&'a BTreeMap<String, V>, WitnessError> {
    let q = object(v).ok_or(WitnessError::Shape)?;
    if q.len() != keys.len() || keys.iter().any(|k| !q.contains_key(*k)) {
        return Err(WitnessError::Shape);
    }
    Ok(q)
}
fn observed_body(v: &V, seq: i64) -> Result<Option<String>, WitnessError> {
    match (seq, v) {
        (0, V::Null) => Ok(None),
        (1..=CARRIER_CAP, V::String(s)) if hex(s) => Ok(Some(s.clone())),
        _ => Err(WitnessError::Shape),
    }
}
impl Witness {
    fn from_value(v: &V) -> Result<Self, WitnessError> {
        let q = closed_value(
            v,
            &[
                "witnessSchema",
                "projectKeyDigest",
                "grantGeneration",
                "seq",
                "bodySha256",
                "state",
            ],
        )?;
        let project = text(&q["projectKeyDigest"])
            .filter(|s| hex(s))
            .ok_or(WitnessError::Shape)?;
        let generation = number(&q["grantGeneration"])
            .filter(|n| *n > 0)
            .ok_or(WitnessError::Shape)?;
        let seq = number(&q["seq"])
            .filter(|n| (0..=CARRIER_CAP).contains(n))
            .ok_or(WitnessError::Shape)?;
        let state = match text(&q["state"]) {
            Some("PENDING") if seq > 0 => WitnessState::Pending,
            Some("COMMITTED") => WitnessState::Committed,
            _ => return Err(WitnessError::Shape),
        };
        if number(&q["witnessSchema"]) != Some(1) {
            return Err(WitnessError::Shape);
        }
        Ok(Self {
            project: project.into(),
            generation,
            seq,
            body: observed_body(&q["bodySha256"], seq)?,
            state,
        })
    }
}
impl CarrierFloor {
    fn from_value(v: &V) -> Result<Self, WitnessError> {
        let q = closed_value(
            v,
            &[
                "highWaterSchema",
                "projectKeyDigest",
                "grantGeneration",
                "lastSeq",
                "tailSha256",
            ],
        )?;
        let project = text(&q["projectKeyDigest"])
            .filter(|s| hex(s))
            .ok_or(WitnessError::Shape)?;
        let generation = number(&q["grantGeneration"])
            .filter(|n| *n > 0)
            .ok_or(WitnessError::Shape)?;
        let seq = number(&q["lastSeq"])
            .filter(|n| (0..=CARRIER_CAP).contains(n))
            .ok_or(WitnessError::Shape)?;
        if number(&q["highWaterSchema"]) != Some(1) {
            return Err(WitnessError::Shape);
        }
        Ok(Self {
            project: project.into(),
            generation,
            seq,
            body: observed_body(&q["tailSha256"], seq)?,
        })
    }
}
// Prospective private operational-file profile108: strict metadata decoding,
// closed value admission, then exact raw == C(value). This is not signed
// metadata/product identity, actual file custody, presence, or quarantine.
#[derive(Debug, PartialEq, Eq)]
enum OperationalFileError {
    Decode(crate::trust::metadata::Error),
    Shape(WitnessError),
    Encode(crate::trust::metadata::Error),
    NonCanonical,
}
struct AdmittedOperationalFile<T> {
    record: T,
    // Exact original bytes for the caller's later observation brackets. Never
    // replace these by a normalized spelling or infer stability from values.
    bytes: Vec<u8>,
}
fn encode_operational_file<T>(
    value: &V,
    admit: fn(&V) -> Result<T, WitnessError>,
) -> Result<Vec<u8>, OperationalFileError> {
    admit(value).map_err(OperationalFileError::Shape)?;
    crate::trust::metadata::encode(value).map_err(OperationalFileError::Encode)
}
fn decode_operational_file<T>(
    raw: &[u8],
    admit: fn(&V) -> Result<T, WitnessError>,
) -> Result<AdmittedOperationalFile<T>, OperationalFileError> {
    let value = crate::trust::metadata::parse(raw).map_err(OperationalFileError::Decode)?;
    let record = admit(&value).map_err(OperationalFileError::Shape)?;
    let canonical = crate::trust::metadata::encode(&value).map_err(OperationalFileError::Encode)?;
    if raw != canonical {
        return Err(OperationalFileError::NonCanonical);
    }
    Ok(AdmittedOperationalFile {
        record,
        bytes: raw.to_vec(),
    })
}
impl Witness {
    fn from_file_bytes(raw: &[u8]) -> Result<AdmittedOperationalFile<Self>, OperationalFileError> {
        decode_operational_file(raw, Self::from_value)
    }
    fn encode_file(value: &V) -> Result<Vec<u8>, OperationalFileError> {
        encode_operational_file(value, Self::from_value)
    }
}
impl CarrierFloor {
    fn from_file_bytes(raw: &[u8]) -> Result<AdmittedOperationalFile<Self>, OperationalFileError> {
        decode_operational_file(raw, Self::from_value)
    }
    fn encode_file(value: &V) -> Result<Vec<u8>, OperationalFileError> {
        encode_operational_file(value, Self::from_value)
    }
}

// Physical presence evidence, distinct from codec/value admission. The caller
// supplies a retained, custody-admitted immediate parent on an admitted local
// filesystem. A path string or this constructor does not establish that custody.
// Writers must publish by replacement; this is not a snapshot of in-place writes.
// These owned observations do not prove cross-file/journal temporal coherence.
#[derive(Debug)]
pub enum OperationalReadFailure {
    Context,
    Bound,
    Io(std::io::Error),
}
#[derive(Debug)]
pub enum OperationalBytesObservation {
    Absent,
    Present(Vec<u8>),
    Unreadable(OperationalReadFailure),
}
fn capture_operational_bytes(
    parent: &opensip_platform::RetainedDirectory,
    leaf: &str,
    max_bytes: usize,
) -> OperationalBytesObservation {
    capture_operational_with_open(parent, leaf, max_bytes, |parent, leaf| {
        parent.open_regular(leaf)
    })
}
// Injection changes only the open/read mechanism in tests; all context and
// parent-linkage checks below are shared with the real File path.
fn capture_operational_with_open<R: std::io::Read>(
    parent: &opensip_platform::RetainedDirectory,
    leaf: &str,
    max_bytes: usize,
    open: impl FnOnce(&opensip_platform::RetainedDirectory, &str) -> std::io::Result<R>,
) -> OperationalBytesObservation {
    capture_operational_checked(parent, leaf, max_bytes, open, || {
        linked_operational_parent(parent)
    })
}
// Shared physical read law. The bound path supplies a complete named-chain
// check; the lower-level descriptor API supplies its explicit immediate-parent
// check. Neither observation establishes continuous custody or exclusion.
fn capture_operational_checked<R: std::io::Read>(
    parent: &opensip_platform::RetainedDirectory,
    leaf: &str,
    max_bytes: usize,
    open: impl FnOnce(&opensip_platform::RetainedDirectory, &str) -> std::io::Result<R>,
    check: impl FnMut() -> Result<(), OperationalReadFailure>,
) -> OperationalBytesObservation {
    match capture_operational_retained(parent, leaf, max_bytes, open, check) {
        Ok(Some((_reader, bytes))) => OperationalBytesObservation::Present(bytes),
        Ok(None) => OperationalBytesObservation::Absent,
        Err(error) => OperationalBytesObservation::Unreadable(error),
    }
}
// Same checks, same opened reader, retained on success for descriptor policy
// checks by the consuming owner. This does not provide exclusion or a snapshot
// against in-place writes; those remain admitted caller preconditions.
fn capture_operational_retained<R: std::io::Read>(
    parent: &opensip_platform::RetainedDirectory,
    leaf: &str,
    max_bytes: usize,
    open: impl FnOnce(&opensip_platform::RetainedDirectory, &str) -> std::io::Result<R>,
    mut check: impl FnMut() -> Result<(), OperationalReadFailure>,
) -> Result<Option<(R, Vec<u8>)>, OperationalReadFailure> {
    // Operational leaves are fixed lowercase constants chosen by the caller.
    // Case-insensitive filesystems do not provide a distinct uppercase identity.
    if leaf.is_empty()
        || matches!(leaf, "." | "..")
        || leaf.contains(['/', '\\', '\0'])
        || leaf.starts_with(".opensip-stage-")
        || max_bytes == 0
        || max_bytes > crate::trust::metadata::MAX_BYTES
    {
        return Err(OperationalReadFailure::Context);
    }
    check()?;
    let opened = open(parent, leaf);
    // ENOENT under an unlinked retained directory does not establish absence.
    // Recheck even when the open failed, before interpreting any open result.
    check()?;
    let mut reader = match opened {
        Ok(reader) => reader,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Ok(None);
        }
        Err(error) => {
            return Err(OperationalReadFailure::Io(error));
        }
    };
    let observed = read_bounded_operational(&mut reader, max_bytes);
    check()?;
    match observed {
        OperationalBytesObservation::Present(bytes) => Ok(Some((reader, bytes))),
        OperationalBytesObservation::Unreadable(error) => Err(error),
        // The bounded reader always returns Present or Unreadable. Keep a
        // defensive refusal if that internal invariant ever changes.
        OperationalBytesObservation::Absent => Err(OperationalReadFailure::Context),
    }
}
fn linked_operational_parent(
    parent: &opensip_platform::RetainedDirectory,
) -> Result<(), OperationalReadFailure> {
    match parent.is_reachable() {
        Ok(true) => Ok(()),
        Ok(false) => Err(OperationalReadFailure::Context),
        Err(error) if error.kind() == std::io::ErrorKind::InvalidInput => {
            Err(OperationalReadFailure::Context)
        }
        Err(error) => Err(OperationalReadFailure::Io(error)),
    }
}
pub(crate) fn read_bounded_operational(
    reader: impl std::io::Read,
    max_bytes: usize,
) -> OperationalBytesObservation {
    use std::io::Read;
    if max_bytes == 0 || max_bytes > crate::trust::metadata::MAX_BYTES {
        return OperationalBytesObservation::Unreadable(OperationalReadFailure::Context);
    }
    // Read at most the limit plus one; never trust inode size or return a prefix
    // as a complete observation. Empty remains Present. A read error, even after
    // successful partial reads, invalidates the entire observation.
    let mut bytes = Vec::new();
    let mut limited = reader.take((max_bytes as u64) + 1);
    if let Err(error) = limited.read_to_end(&mut bytes) {
        return OperationalBytesObservation::Unreadable(OperationalReadFailure::Io(error));
    }
    if bytes.len() > max_bytes {
        return OperationalBytesObservation::Unreadable(OperationalReadFailure::Bound);
    }
    OperationalBytesObservation::Present(bytes)
}

