#[cfg(test)]
mod witness_tests {
    use super::*;
    #[test]
    fn actual_witness_floor_shape_and_reconciliation_reference_cases() {
        let V::Object(corpus) = opensip_identity::parse_json(WITNESS_CASES.as_bytes()).unwrap()
        else {
            panic!("object")
        };
        let V::Array(shape) = &corpus["shape"] else {
            panic!("shape")
        };
        for (i, c) in shape.iter().enumerate() {
            let q = object(c).unwrap();
            let raw = text(&q["raw"]).unwrap();
            let kind = text(&q["kind"]).unwrap();
            let V::Bool(expected) = q["admit"] else {
                panic!("bool")
            };
            let actual = opensip_identity::parse_json(raw.as_bytes()).is_ok_and(|v| {
                if kind == "witness" {
                    Witness::from_value(&v).is_ok()
                } else {
                    CarrierFloor::from_value(&v).is_ok()
                }
            });
            assert_eq!(actual, expected, "shape{i} {kind}");
        }
        let V::Array(cases) = &corpus["reconcile"] else {
            panic!("reconcile")
        };
        for (i, c) in cases.iter().enumerate() {
            let q = object(c).unwrap();
            let tail = ObservedTail::from_value(&q["tail"]);
            let witness = Witness::from_value(&q["witness"]);
            let t = if q["tail"] == V::Null {
                TailObservation::Empty
            } else if let Ok(t) = &tail {
                TailObservation::Present(t)
            } else {
                TailObservation::Malformed
            };
            let w = if q["witness"] == V::Null {
                WitnessObservation::Absent
            } else if let Ok(w) = &witness {
                WitnessObservation::Present(w)
            } else {
                WitnessObservation::Malformed
            };
            let proposal = reconcile_observations(
                text(&q["project"]).unwrap(),
                number(&q["generation"]).unwrap(),
                t,
                w,
            );
            let actual = match proposal {
                WitnessProposal::Consistent => "OK",
                WitnessProposal::Initialize => "INIT",
                WitnessProposal::Revert => "REVERT",
                WitnessProposal::Advance => "ADVANCE",
                WitnessProposal::Quarantine => "QUARANTINE",
                WitnessProposal::Unavailable => "UNAVAILABLE",
            };
            assert_eq!(actual, text(&q["action"]).unwrap(), "reconcile{i}");
        }
    }
    #[test]
    fn unreadable_is_never_converted_into_absent_or_a_write_proposal() {
        assert_eq!(
            reconcile_observations(
                "project",
                1,
                TailObservation::Unreadable,
                WitnessObservation::Absent
            ),
            WitnessProposal::Unavailable
        );
        assert_eq!(
            reconcile_observations(
                "project",
                1,
                TailObservation::Empty,
                WitnessObservation::Unreadable
            ),
            WitnessProposal::Unavailable
        );
        assert_eq!(
            reconcile_observations(
                "project",
                1,
                TailObservation::Empty,
                WitnessObservation::Absent
            ),
            WitnessProposal::Initialize
        );
        assert_eq!(
            reconcile_observations(
                "project",
                1,
                TailObservation::Empty,
                WitnessObservation::Malformed
            ),
            WitnessProposal::Quarantine
        );
    }
}

